script:
frappe.ui.form.on('Project', {
	refresh(frm) {
		frm.trigger("render_financial_charts");
	},

	render_financial_charts(frm) {
		const sales_amount = frm.doc.total_billed_amount || 0;
		const purchase_amount = frm.doc.total_purchase_cost || 0;

		frm.dashboard.clear_headline();

		frm.dashboard.set_headline(`
			<div style="
				display:flex;
				flex-wrap:wrap;
				gap: 5px;
				min-height:300px;
				background: transparent;
				border-radius:12px;
				font-family: var(--font-family);
			">

				<div style="
					flex:1;
					min-width:300px;
					background: var(--card-bg);
					border-radius:10px;
					padding:16px;
					box-shadow: var(--card-shadow);
				">
					<div id="project_sales_purchase_bar" style="height:220px;"></div>
				</div>

				<div style="
					flex:1;
					min-width:300px;
					background: var(--card-bg);
					border-radius:10px;
					padding:16px;
					box-shadow: var(--card-shadow);
				">
					<div id="project_sales_purchase_pie" style="height:220px;"></div>
				</div>

			</div>
		`);

		setTimeout(() => {
			const bar_el = document.getElementById("project_sales_purchase_bar");
			const pie_el = document.getElementById("project_sales_purchase_pie");

			if (!bar_el || !pie_el) return;

			const data = {
				labels: ["Sales Invoice", "Purchase Invoice"],
				datasets: [
					{
						name: "Amount",
						values: [sales_amount, purchase_amount]
					}
				]
			};

			new frappe.Chart(bar_el, {
				title: "Sales vs Purchases",
				data,
				type: "bar",
				height: 220,
				colors: ["#21ba45", "#db2828"]
			});

			new frappe.Chart(pie_el, {
				title: "Financial Distribution",
				data,
				type: "pie",
				height: 220,
				colors: ["#21ba45", "#db2828"]
			});
		}, 300);
	}
});
